size_t iterations = 0;
const size_t max_iterations = ckh->max_iterations;
size_t bucket = argbucket;
const void *key = argkey;
const void *data = argdata;
while (iterations < max_iterations) {
    if (ckh->insert(bucket, key, data)) {
        return false;
    }
    // Evict and relocate
    size_t evicted_bucket = ckh->evict(bucket);
    const void *evicted_key = ckh->get_key(evicted_bucket);
    const void *evicted_data = ckh->get_data(evicted_bucket);
    // Update bucket and key for next iteration
    bucket = ckh->hash(evicted_key) % ckh->num_buckets;
    key = evicted_key;
    data = evicted_data;
    iterations++;
}
return true;

